import type { SpeakingMockPack, SpeakingQuestionResponse } from './speaking-model.js';
const q = (prompt: string, answer: string): SpeakingQuestionResponse => ({ prompt, answer });

export const speakingMockPacksB: SpeakingMockPack[] = [
  { topic: 'Learning a few words for a new neighbour', band: 3, part1: [
    q('When do you use a language other than your first language?', 'I use English in a study group and sometimes when helping visitors. Most of my daily conversations are still in my first language, so practice needs some planning.'),
    q('Which short expressions are easiest for you to learn?', 'Expressions I can use immediately are easiest, such as asking for a price. Repeating a phrase in a real situation helps me remember it better than reading a list.'),
    q('Do you enjoy hearing different languages around you?', 'I do, especially when I can recognise a familiar word. I do not need to understand everything to appreciate that people have different ways of expressing everyday ideas.'),
    q('Would you practise pronunciation with another learner?', 'Yes, if we were comfortable correcting each other politely. A shared exercise feels less frightening than speaking alone in front of someone who already knows the language well.'),
    q('What helps you continue when language learning feels difficult?', 'I think about one practical task I can do better than before. Noticing a small improvement keeps me motivated when the whole language still seems too large to learn.'),
  ], cue: 'Describe a time when learning a few words helped you connect with someone.', points: ['who the person was', 'which words you learned', 'how you learned them', 'and explain how the person responded'], answer: 'I learned a few greetings to welcome a new neighbour who had moved from another country. We could communicate in English, but she mentioned that hearing her own language made her feel less far from home. I did not have time to study it properly, yet I thought learning a small number of words would be a friendly beginning.\n\nI used a reliable introductory recording to practise saying hello and thank you. Then I asked her to check the pronunciation rather than assume the recording alone was enough. She corrected one sound and explained that the greeting had a more formal version for older people. We laughed at my first attempt, but she was pleased that I had tried. Later, I used the greeting when we met near the lift.\n\nThe words did not suddenly allow us to have a conversation in her language. Their value was that they showed interest and gave her a chance to teach me something familiar. She began asking about expressions in my language too. I enjoyed that the exchange worked in both directions. It reminded me that language learning can support a relationship even before a person has advanced vocabulary or perfect pronunciation.', part3: [
    q('Why can a small effort to use another language have social value?', 'It shows attention to the other person’s background and may reduce the feeling that they must always adapt. The effort should be respectful rather than a performance. Even a greeting can begin an exchange, although meaningful communication still requires listening and patience.'),
    q('Should newcomers be expected to learn the local language immediately?', 'Learning it is useful, but expecting rapid fluency ignores differences in age, work and educational experience. Accessible opportunities are more constructive than blame. Essential services should remain understandable during the learning period, especially when misunderstanding could have serious consequences.'),
    q('Can language exchanges work when participants have different abilities?', 'They can if each person has realistic goals and enough time to practise. One participant may need basic conversation while another wants detailed discussion. Taking turns and agreeing on suitable activities prevents the more fluent speaker from controlling the whole exchange.'),
    q('How important is correct pronunciation compared with willingness to speak?', 'Both matter, but perfect pronunciation is not a reasonable condition for participation. Learners need to be understandable and willing to clarify. Patient feedback improves accuracy over time, whereas constant interruption may discourage the practice that would actually help them improve.'),
    q('Does translation technology remove the need to learn languages?', 'It helps with many practical tasks, but it does not fully replace the relationships and understanding built through direct communication. It can also misread context. Learning remains valuable even when technology provides a useful backup for unfamiliar words or urgent information.'),
  ] },
  { topic: 'A shop that made ordering easier', band: 3.5, part1: [
    q('How do you choose where to buy everyday groceries?', 'I choose a shop that is close and has reliable opening hours. A small difference in price matters less than knowing I can find what I need on the way home.'),
    q('Do you enjoy speaking to people who work in shops?', 'I enjoy a brief conversation if the shop is not busy. Asking about an unfamiliar item can be useful, but I do not expect staff to talk when customers are waiting.'),
    q('Would you order groceries for another person?', 'I would if they explained their preferences clearly. I would confirm any substitute rather than decide that something different was suitable without asking them.'),
    q('Have you used a telephone to place a shop order?', 'I called a bakery to reserve bread for a family lunch. It was straightforward because I knew the product name and could collect it at an agreed time.'),
    q('What makes a local shop convenient apart from its location?', 'Clear prices and a simple way to ask questions help a lot. A nearby shop is less convenient if I cannot tell what is available or when an order will be ready.'),
  ], cue: 'Describe a service change that helped someone you know.', points: ['who benefited', 'what the service changed', 'how the person used it', 'and explain why the change made a difference'], answer: 'A small grocery shop began accepting telephone orders, which helped my aunt when she was recovering from a leg injury. The shop already had a website, but she did not feel comfortable selecting items online. Before the change, a relative had to visit her, collect a list and then return with the shopping.\n\nThe owner introduced a short telephone-order period each morning and arranged local deliveries twice a week. My aunt could describe the items she wanted and ask about anything unfamiliar. If a product was unavailable, the staff member explained the options rather than choosing a substitute automatically. She paid in the way agreed with the shop and kept the receipt so she could check the order later.\n\nThe change made a difference because it gave her more control over an ordinary part of life while she could not walk comfortably. It did not mean family members stopped visiting or helping. Instead, our visits could focus less on errands and more on spending time together. I appreciated that the shop added an accessible option without removing its existing website. A service can become more inclusive by offering another practical route, rather than expecting every customer to become comfortable with the same technology.', part3: [
    q('Why is offering several ways to access a service sometimes important?', 'People differ in mobility, confidence and access to technology, so one method can exclude otherwise capable users. Multiple options also provide a backup when a system fails. The organisation must keep the information consistent, however, or choice may create new confusion.'),
    q('Should businesses provide personal assistance even when online systems are cheaper?', 'Some assistance is necessary when customers cannot reasonably use the system or need clarification. The cost must be considered, but excluding users can also harm the business. A proportionate approach might combine efficient online tasks with accessible help for specific difficulties.'),
    q('How can a service support independence without removing human contact?', 'It can let users choose and control routine decisions while keeping opportunities for conversation or assistance. Independence does not require doing everything alone. A well-designed service reduces unnecessary dependence without assuming that social interaction is an inefficient part of the process.'),
    q('What should a shop consider before offering delivery?', 'It should assess demand, staffing and realistic delivery times, then explain any limits clearly. A convenient promise can become frustrating if it is unreliable. Staff also need a process for substitutions, payments and mistakes so customers retain control over their purchases.'),
    q('Can a small business be more adaptable than a large chain?', 'It may respond quickly to local needs because decision-makers know customers directly. However, it often has fewer resources and less spare capacity. Adaptability is an advantage only when the change can be maintained without placing unreasonable pressure on the people running the business.'),
  ] },
  { topic: 'Borrowing tools from a neighbourhood library', band: 4, part1: [
    q('Do you own items that you use only occasionally?', 'I have a large cooking pot that comes out for family gatherings. It is useful, but it occupies a lot of space between those occasions.'),
    q('Would you lend a household item to a neighbour?', 'Yes, if we agreed on when it would be returned and how it should be used. Clear arrangements make lending feel friendly rather than uncertain.'),
    q('Have you visited a place where people share equipment?', 'I visited a community workshop where several people used the same basic tools. A volunteer explained the rules, which helped beginners feel welcome without compromising safety.'),
    q('How do you decide whether to buy or borrow something?', 'I consider how often I will use it and whether borrowing is reliable. Buying makes sense for a regular need, but not always for one short task.'),
    q('Do you like learning how to use unfamiliar tools?', 'I enjoy it with proper guidance. Guessing can be frustrating or unsafe, so I prefer a demonstration and a chance to ask questions before beginning.'),
  ], cue: 'Describe a shared resource that you found particularly useful.', points: ['what the resource was', 'how you accessed it', 'what you used it for', 'and explain what made the arrangement work well'], answer: 'I found a neighbourhood tool library useful when I needed to clean a small patio. It was run from a community centre and lent equipment for short periods. I had heard about it from a notice, but I checked the rules online before visiting because I did not know whether beginners could borrow the larger items.\n\nA volunteer helped me choose a suitable cleaning tool and explained how to use it safely. We checked its condition together and noted the return date. I borrowed it for a weekend, completed the task slowly and cleaned the equipment according to the instructions before bringing it back. There was a small borrowing fee that supported maintenance, which seemed reasonable compared with buying something I would rarely need.\n\nThe arrangement worked well because responsibility was clear. Sharing did not mean simply taking equipment and hoping someone else would look after it. The library maintained the tools, while borrowers agreed to use and return them properly. I also appreciated being able to ask a practical question without feeling I was wasting a shop assistant’s time. The experience made me consider shared options for occasional tasks, especially when storing an item at home would be less useful than having reliable access to it.', part3: [
    q('What conditions make a sharing scheme reliable?', 'Users need clear rules, maintained equipment and a realistic booking system. Trust is helpful, but it should be supported by practical arrangements rather than assumed. If responsibilities are vague, considerate users may end up carrying the cost of damage or late returns.'),
    q('Can borrowing reduce unnecessary consumption?', 'It can for items used rarely, because several households may share one durable product instead of buying separate versions. The benefit depends on transport and maintenance too. A borrowing system that is difficult to reach may not be a practical alternative for everyone.'),
    q('Should community schemes charge a fee?', 'A modest fee can support upkeep and make the service sustainable, provided it does not exclude people who need it most. Concessions or public support may help. Free access is attractive, but somebody still has to cover repairs, space and administration.'),
    q('How should a scheme respond when someone returns damaged equipment?', 'It should first establish what happened and apply a clear policy consistently. Normal wear differs from careless use, and users should know that distinction beforehand. A reasonable response protects the shared resource without discouraging honest reporting of a problem.'),
    q('Why might some people prefer owning an item even if they rarely use it?', 'Ownership provides immediate access and removes the need to organise borrowing. Some people also value privacy or dislike relying on others. Those preferences are understandable, though they can be weighed against cost and storage when a reliable shared option exists nearby.'),
  ] },
  { topic: 'Finding a suitable place for focused study', band: 4.5, part1: [
    q('What time of day is best for difficult study tasks?', 'Late morning suits me because I am fully awake but not yet tired. I use evenings for revision rather than attempting the most demanding new material.'),
    q('Do you prefer studying beside other learners?', 'I like knowing that others are studying nearby, provided we are not expected to talk continuously. It creates a focused atmosphere while allowing each person to work at a different pace.'),
    q('What do you prepare before a study session?', 'I choose one main task and put the necessary materials on the desk. Preparing too many topics at once makes it easier to switch around without completing anything.'),
    q('Would a change of location help if you felt distracted?', 'Sometimes it would, especially if the distraction came from noise or household tasks. If I was avoiding a difficult question, though, changing rooms would not solve the real issue.'),
    q('How do you know when it is time to take a study break?', 'I notice that I am reading the same paragraph without understanding it. A short break is then more useful than continuing simply to reach a planned number of minutes.'),
  ], cue: 'Describe a place you chose for studying and explain why it suited a particular task.', points: ['where the place was', 'what you needed to study', 'what features helped you', 'and explain how successful the session was'], answer: 'I chose a small study room at the college for reviewing a difficult chapter about statistics. At home, I kept interrupting myself with simple chores whenever the examples became confusing. I wanted a place where the only sensible activity was to work through the chapter patiently.\n\nThe room could be booked for a short period and had a plain desk, good lighting and a whiteboard. I took only the textbook, a notebook and a few printed exercises. The whiteboard helped because I could leave one calculation visible while comparing it with another, instead of repeatedly turning pages. There were other learners in nearby rooms, but the walls reduced conversation enough for me to concentrate. I also knew the booking ended after ninety minutes, which encouraged me to choose a realistic target.\n\nThe session was successful because I finally understood two examples I had been avoiding. I did not finish the whole chapter, and I made a note of one question to ask the tutor. That limited result still felt valuable. The place suited the task because it reduced unnecessary choices and gave me space to organise the reasoning. I would not use it for every kind of study, but it was a useful option when concentration and a visible sequence of steps mattered.', part3: [
    q('What features matter most in a space intended for learning?', 'The answer depends on the activity, but adequate light, comfortable seating and control of noise are broadly important. Some learning requires discussion, while other work needs quiet. A useful space recognises those differences instead of assuming one arrangement suits every learner.'),
    q('Can a strict timetable improve concentration?', 'It can create a clear beginning and end, making a task feel manageable. However, an unrealistic timetable may encourage rushing or discourage someone who needs more time. Planning should support attention while leaving room to adjust when the material proves more demanding than expected.'),
    q('Should colleges provide rooms for individual study as well as group work?', 'Yes, because the two activities have different demands and both are important. Access should be fair and booking rules clear. Providing only collaborative areas can disadvantage learners who need quiet, while only silent rooms would limit valuable discussion and shared problem solving.'),
    q('Why do learners sometimes confuse time spent with progress made?', 'Time is easy to measure, whereas understanding is harder to judge. Sitting at a desk for hours can therefore feel productive even when attention is poor. Clear tasks and checking what can be explained afterwards give a more useful indication of progress.'),
    q('How can teachers encourage learners to ask about uncertainty?', 'They can make questions a normal part of learning and respond without treating confusion as failure. Asking students to identify one unclear point can help. Teachers should also show how to formulate a specific question, since knowing what one does not understand is itself a skill.'),
  ] },
  { topic: 'A visit to a working farm', band: 5, part1: [
    q('Do you like learning where everyday food comes from?', 'I do, especially when I can connect the explanation with something I buy regularly. Seeing the work behind a simple product makes the price easier to understand.'),
    q('Have you spent much time in the countryside?', 'I visited relatives there during school holidays, but I have mainly lived in towns. I enjoy the quieter setting while recognising that daily rural life involves work, not just scenery.'),
    q('Would you enjoy helping with an outdoor task for a morning?', 'Yes, if the task matched my ability and someone showed me what to do. I would rather be genuinely useful than try an unfamiliar job and create extra work.'),
    q('What do you usually notice first when visiting a rural place?', 'I notice the amount of open space and then the sounds. Without constant traffic, small noises such as birds or machinery seem much more distinct.'),
    q('Do you buy food directly from producers when possible?', 'Occasionally at a weekend market. I appreciate being able to ask about the product, although I still consider price and whether I can use it before it spoils.'),
  ], cue: 'Describe a visit that helped you understand how food is produced.', points: ['where you went', 'what was produced there', 'what you saw or learned', 'and explain what interested you most'], answer: 'I visited a small dairy farm during an organised open day. A friend had found the event, and we booked because the visit included a short explanation of how the farm’s cheese was made. I had seen cheese production in videos but had never connected it with the daily work of caring for the animals.\n\nThe farmer began by explaining the routine and the rules visitors needed to follow. We watched from designated areas rather than entering every working space. Later, a member of the production team described the stages using photographs and a demonstration with clean equipment. She explained that similar ingredients could produce different results depending on timing and the conditions used. I was particularly interested in how much checking was required before a product could be sold.\n\nThe visit helped me understand that the finished item represented a sequence of responsibilities, not one simple action. I enjoyed the tasting at the end, but the practical explanation mattered more. It also reminded me that an open day shows only part of a working business; a pleasant morning visit is not the same as managing it all year. I left with greater appreciation for the people involved and more curiosity about the origins of ordinary food.', part3: [
    q('Why can visits to producers be useful for consumers?', 'They reveal processes and constraints that packaging rarely explains, helping people make more informed choices. However, a visit is usually selective and should not be treated as a complete inspection. Its value lies in improved understanding and opportunities to ask relevant questions.'),
    q('Should children learn more about food production?', 'Yes, age-appropriate learning can connect everyday meals with farming, transport and storage. It should reflect different production methods rather than present one idealised picture. Practical visits may help, but well-designed classroom activities are also valuable when travel is difficult.'),
    q('How can farms welcome visitors without disrupting their work?', 'They can set clear times, routes and group limits, with someone responsible for explanations. Safety and animal welfare should take priority over giving unrestricted access. A structured visit can be engaging while respecting that the farm remains a workplace rather than an amusement venue.'),
    q('Does buying locally always mean buying more responsibly?', 'Local purchasing may reduce some transport and support nearby businesses, but distance is not the only factor. Production methods, waste and working conditions also matter. Consumers need proportionate information rather than a simple label that claims to settle every environmental or ethical question.'),
    q('What makes a producer’s explanation credible?', 'It should include practical limits and verifiable information, not only attractive claims. Acknowledging difficulties can strengthen trust when accompanied by clear action. Consumers should still distinguish a helpful explanation from independent evidence, especially when a claim concerns health, sustainability or welfare.'),
  ] },
  { topic: 'Making an announcement easier to understand', band: 5.5, part1: [
    q('Do you read notices displayed in public buildings?', 'I read them if the heading suggests something relevant to my visit. A clear title helps me decide quickly whether I need the information or can move on.'),
    q('Would you volunteer to write a short announcement?', 'I would if I understood the event and the intended audience. Writing a short notice can be harder than it looks because every important detail has to fit clearly.'),
    q('How do you check whether your writing is clear?', 'I read it as if I knew nothing about the topic and ask someone to point out missing information. Spelling checks alone cannot show whether the message makes sense.'),
    q('Do you prefer detailed instructions or a quick summary?', 'A quick summary is useful first, followed by detail if the task requires it. Starting with too much explanation can hide the main action I need to take.'),
    q('Have you ever missed an event because the information was unclear?', 'I once arrived on the wrong day because an old poster remained beside a new one. Since then I check the full date rather than just the weekday.'),
  ], cue: 'Describe a time when you helped make written information clearer.', points: ['what the information was for', 'what was confusing about it', 'what you changed', 'and explain how you checked the result'], answer: 'I helped rewrite a notice about a change to our community centre’s opening hours. The original version began with a long explanation of maintenance work and placed the new times near the bottom. Several visitors had asked whether the centre was closing completely, even though only one entrance and two evening sessions were affected.\n\nI suggested putting the main change in the first sentence, followed by a short list of dates and available entrances. We kept the reason for the work, but moved the technical details to a separate section. I also replaced a few abbreviations with ordinary words and made the start and end dates equally prominent. The manager checked that we had not accidentally removed an important condition.\n\nTo test the result, we asked two volunteers who had not seen the earlier version to explain what they would do if visiting on Tuesday evening. Their answers showed that one phrase was still unclear, so we revised it before printing. The new notice did not attract much attention, which was actually a good result: people could understand it quickly and continue with their plans. The experience taught me that clear writing depends on the reader’s task, not simply shorter sentences or a more attractive design.', part3: [
    q('Why does public information sometimes become unnecessarily complicated?', 'Writers may begin from the organisation’s internal process rather than the user’s question. They may also fear omitting a condition and include everything at once. Organising essential actions first and supporting details afterwards can preserve accuracy without making the message difficult to use.'),
    q('Should important notices be tested with ordinary users?', 'For information that affects many people, simple user testing can reveal misunderstandings before they cause inconvenience. It does not have to be expensive or extensive. Asking someone to explain the action they would take is often more revealing than asking whether the notice looks clear.'),
    q('Is plain language suitable for every subject?', 'It is useful even for complex subjects, but it does not mean removing necessary distinctions. A technical term can be included with an explanation when it matters. The aim is to reduce avoidable difficulty while preserving the meaning, not to make every idea appear simple.'),
    q('How can design support accurate communication?', 'Headings, spacing and consistent emphasis help readers find dates, actions and exceptions. Design should guide attention according to importance. Highlighting everything equally or using decorative text can make a notice attractive while leaving the actual message harder to locate.'),
    q('Who is responsible when outdated information remains publicly displayed?', 'The organisation needs a clear process for removing or correcting it, even if one person originally wrote the notice. Users cannot always know which version is current. Assigning responsibility for updates is therefore part of providing information, not an optional task after publication.'),
  ] },
  { topic: 'Trying an adult dance class', band: 6, part1: [
    q('Do you like activities that involve moving to music?', 'I enjoy informal movement more than a formal performance. Following a rhythm can be relaxing, especially when nobody expects every step to look polished.'),
    q('Would you join a beginner class without knowing anyone?', 'I would if the description made clear that complete beginners were welcome. Arriving slightly early would help me understand the room and speak to the instructor before starting.'),
    q('How do you feel when learning a movement takes several attempts?', 'I can become impatient, but breaking it into smaller parts helps. Once I understand the sequence, repeating it feels purposeful rather than simply making the same mistake again.'),
    q('Do you prefer learning through explanation or demonstration?', 'For movement, a demonstration is essential. A short explanation then helps me understand where to place my weight or why a particular order matters.'),
    q('What would make a group activity enjoyable for you?', 'A welcoming pace and permission to ask questions would matter most. I enjoy a challenge, but not an atmosphere where newcomers feel they are delaying everyone else.'),
  ], cue: 'Describe an activity that you tried even though you did not expect to be good at it.', points: ['what the activity was', 'why you decided to try it', 'what happened when you participated', 'and explain how you felt afterwards'], answer: 'I tried a beginner dance class despite expecting to be quite clumsy. A friend had received two places at an introductory session and asked me to join her. I agreed mainly because the class was described as relaxed and suitable for people with no experience, rather than because I had any ambition to perform.\n\nThe instructor began with a short sequence of steps and encouraged us to practise without music first. I kept turning in the wrong direction, but she showed how to connect the turn with the previous step instead of treating it as a separate movement. We changed partners several times, so nobody had to remain with the most confident person or the least confident person. When the music started, I forgot part of the sequence and laughed, then rejoined at the next familiar step.\n\nAfterwards, I felt tired in a pleasant way and less embarrassed about being a beginner. I had not become especially skilled, but I had enjoyed concentrating on something outside my normal routine. The instructor’s approach mattered: mistakes were information for practice, not evidence that someone did not belong. I returned for another session the following month, this time because I genuinely wanted to continue rather than simply accompany a friend.', part3: [
    q('Why can adults be reluctant to begin an unfamiliar activity?', 'They may be accustomed to competence in other areas and dislike being visibly inexperienced. Time and cost also affect willingness. A welcoming beginner environment helps, but adults need realistic opportunities rather than being told that reluctance is only a lack of courage.'),
    q('Should recreational classes separate learners by ability?', 'Some separation can make teaching more appropriate and reduce frustration, particularly where safety or pace matters. However, rigid levels may discourage movement between groups. Occasional shared activities can allow people to learn from one another without ignoring significant differences in experience.'),
    q('How can an instructor respond constructively to mistakes?', 'They can identify the part causing difficulty and offer a manageable adjustment rather than repeat a general instruction louder. Demonstration and practice help. The response should preserve dignity, especially in a group, because embarrassment can interfere with the attention needed to improve.'),
    q('Does an activity need to produce measurable improvement to be worthwhile?', 'Not always. Enjoyment, social contact and a change from routine can justify participation even when progress is modest. Measurement may support a specific goal, but treating every leisure activity as a performance test can remove the relaxation it was meant to provide.'),
    q('What benefits can movement-based classes offer beyond exercise?', 'They can develop coordination, attention and confidence in using shared space. Group activities may also create social connections. Those benefits depend on the experience being welcoming and appropriate; a competitive or uncomfortable class will not affect every participant in the same positive way.'),
  ] },
  { topic: 'Watching a craft worker demonstrate printing', band: 6.5, part1: [
    q('Do you notice how everyday objects have been made?', 'I notice it when an object has an unusual texture or visible join. Looking closely can make a simple item more interesting than judging only its colour or shape.'),
    q('Would you enjoy watching someone work in a studio?', 'Yes, provided the visit did not interrupt their concentration. Seeing the sequence of decisions would interest me more than being allowed to handle every tool.'),
    q('Have you bought a small item directly from its maker?', 'I bought a printed card at a local fair. The maker explained how several colours were added separately, which helped me appreciate the care behind a small object.'),
    q('What kind of creative skill would you like to try briefly?', 'I would like to try simple printmaking. Repeating one design with slight variations sounds enjoyable, and it would be different from drawing a complete picture each time.'),
    q('Do you prefer a handmade item to look perfectly regular?', 'Not necessarily. A small variation can show how it was made, although I would still expect the item to function properly if it had a practical purpose.'),
  ], cue: 'Describe a demonstration by someone skilled that you enjoyed watching.', points: ['who gave the demonstration', 'what they demonstrated', 'which part you found interesting', 'and explain what you understood afterwards'], answer: 'I watched a printmaker demonstrate how she produced a two-colour image from separate carved blocks. The demonstration took place during an open afternoon at a shared arts studio. I had seen finished prints before, but I assumed the process was mostly a matter of pressing an image onto paper.\n\nShe first showed how the design had to be reversed on the block. Then she applied a thin layer of ink and carefully positioned the paper against small guides. The most interesting part was adding the second colour. A tiny difference in alignment changed the whole appearance, so she checked several points before applying pressure. One early print was imperfect, and she used it to explain the adjustment rather than hiding it from the visitors.\n\nAfterwards, I understood why a repeated image still involved judgement each time. The materials and pressure could affect the result even when the design remained the same. I also appreciated the preparation behind what looked like a quick final action. The demonstration made me more willing to look closely at prints instead of comparing them only with digital images. I did not leave thinking that handmade work was automatically better, but I had a clearer idea of the particular skill and attention this method required.', part3: [
    q('Why can demonstrations increase appreciation of a craft?', 'They reveal decisions and difficulties hidden in the finished object, helping observers understand what skilled work involves. However, a brief demonstration shows only part of the process. It should create informed interest rather than imply that watching once is equivalent to learning the craft.'),
    q('Should craftspeople explain imperfections in their work?', 'When relevant, explaining a variation can help buyers distinguish a deliberate feature from a defect. It should not excuse poor function or careless finishing. Honest discussion allows people to appreciate the method while still making a reasonable judgement about the quality of the object.'),
    q('Can traditional methods remain useful alongside digital production?', 'Yes, they can offer different textures, working experiences and possibilities for experimentation. Digital methods may also support planning or distribution. The relationship need not be competitive in every case; makers can combine tools according to the purpose of a particular piece.'),
    q('What makes learning a craft different from watching instructions?', 'Learning requires handling materials, noticing resistance and adjusting after feedback. Instructions provide a starting point but cannot anticipate every small variation. Repeated practice develops judgement, which is why an apparently simple action may take much longer to perform consistently than to describe.'),
    q('How can open studios benefit a local community?', 'They can make creative work accessible and connect makers with potential audiences or collaborators. The visits must be organised so work can continue and safety is maintained. An open studio is most valuable when it offers genuine explanation rather than only another opportunity to sell products.'),
  ] },
  { topic: 'A map that revealed an old route', band: 7, part1: [
    q('Do you enjoy comparing old and new photographs of a place?', 'I enjoy noticing what has stayed the same as well as what changed. A doorway or street corner can provide a connection when most of the surrounding buildings look different.'),
    q('Would you visit an archive to learn about your area?', 'I would if I had a clear question and knew how to begin. A brief introduction to the catalogue would make the visit less intimidating.'),
    q('What details do you remember from a place you visited years ago?', 'I tend to remember sounds and routes better than exact addresses. A particular staircase or the smell near a bakery can remain clear after many names have faded.'),
    q('Do you ask relatives how your hometown used to look?', 'Sometimes, especially when a familiar building changes use. Their accounts help me imagine the place, although I know people remember different aspects of the same period.'),
    q('Would you follow a historical walking route?', 'Yes, if it included clear explanations and reasonable distances. I would enjoy connecting information with visible features rather than reading about the area entirely indoors.'),
  ], cue: 'Describe a document that helped you understand a place better.', points: ['what the document was', 'where you found it', 'what it showed', 'and explain how it changed your understanding'], answer: 'An old map helped me understand why a narrow park in my city followed such an unusual curved route. I found the map in a small local-history display at the library while waiting for a friend. The park had always seemed like an oddly shaped strip of land between ordinary streets.\n\nThe map showed that the same line had once been a small industrial railway connecting workshops with the main station. A later label explained when the tracks were removed and which parts of the route remained visible. I compared the old street names with a current map on my phone and realised that several bends in the park corresponded with the original railway. The display also included a photograph, which supported the explanation without showing every stage of the change.\n\nIt changed my understanding because the shape no longer seemed accidental. I could see how an earlier use of land had influenced the present neighbourhood. The next time I walked through the park, I noticed a low wall and the spacing between buildings more carefully. I did not assume that every old feature must be preserved forever, but I appreciated the continuity. A document that looked rather plain had made an ordinary local walk more meaningful by connecting its present form with a practical history.', part3: [
    q('Why is it useful to understand the earlier uses of urban land?', 'Earlier uses can explain present layouts, infrastructure and environmental issues that otherwise seem puzzling. That knowledge supports planning as well as historical interest. It should inform decisions without implying that every past arrangement must be restored or that change is automatically undesirable.'),
    q('Can a map tell the whole story of a place?', 'No, it shows selected spatial information for a particular purpose and may omit how people experienced the area. Maps are valuable evidence, but they need context. Comparing them with photographs, records and personal accounts gives a richer understanding of what the place was like.'),
    q('Should cities mark historical features that are no longer visible?', 'A modest sign or route can help people understand continuity without requiring reconstruction. The choice should consider significance and accuracy rather than marking every vanished object. Too much information can become clutter, so explanations need to be selective and accessible.'),
    q('How can historical information influence redevelopment responsibly?', 'It can identify valuable features, explain local identity and reveal constraints, while allowing new needs to be considered. Responsible use avoids both ignoring the past and treating it as a fixed model. A design should explain what is retained, changed or removed and why.'),
    q('Why do people sometimes disagree about local history?', 'They may rely on different evidence or remember experiences from different social positions. Familiar stories can also become accepted without checking. Disagreement can be productive when sources are examined respectfully, rather than assuming one person’s strong attachment proves every detail of their account.'),
  ] },
  { topic: 'A trial of more flexible working hours', band: 7.5, part1: [
    q('Do you prefer beginning important tasks early?', 'I prefer beginning early enough to avoid pressure, but not necessarily early in the morning. My attention is better when I have had time to prepare the materials and understand the goal.'),
    q('How does your routine change when you work from home?', 'I need clearer boundaries between work and ordinary household tasks. At the office, the setting provides those boundaries, while at home I have to create them deliberately.'),
    q('Would you choose your own working hours if possible?', 'I would appreciate some choice, particularly around travel, but I would still need shared times for collaboration. Complete freedom can become inconvenient if nobody knows when others are available.'),
    q('Do you find short meetings useful?', 'They are useful when there is a clear decision to make. A short meeting without preparation can waste less time than a long one, but it may still leave the same confusion.'),
    q('What helps you finish work at a reasonable time?', 'Choosing the final task before the day becomes busy helps. Otherwise I keep beginning small additional jobs and find that the evening has disappeared without a clear stopping point.'),
  ], cue: 'Describe a change in a schedule that improved your daily life.', points: ['what the schedule was like before', 'what change was introduced', 'how you adapted', 'and explain why the change helped'], answer: 'A change in my workplace schedule improved my journey to work. Previously, everyone began at the same time, which meant travelling during the busiest part of the morning. The organisation introduced a trial that allowed some staff to start earlier or later, provided there were shared hours for meetings and customer contact.\n\nI chose a slightly earlier start. At first I worried that getting up earlier would make me tired, so I adjusted my evening routine rather than simply cutting sleep. I prepared lunch before dinner and avoided beginning long tasks late at night. The quieter journey saved a modest amount of time, but the more noticeable benefit was arriving without the stress of a crowded bus. I also finished early enough to buy groceries before the shops became busiest.\n\nThe change helped because it gave me a useful choice within clear limits. It did not solve every work problem, and colleagues with school runs preferred a different schedule. During the review, we discussed whether the shared hours were sufficient and whether any duties had become harder to cover. I appreciated that the trial was evaluated rather than declared successful automatically. The arrangement worked for me because it matched my circumstances, not because an earlier start would necessarily suit everyone.', part3: [
    q('What should an employer consider before introducing flexible hours?', 'They should examine service needs, collaboration and which tasks genuinely require simultaneous attendance. Staff circumstances also matter. A clear trial with feedback can reveal problems before a permanent decision, rather than assuming flexibility is either universally beneficial or impossible for the entire organisation.'),
    q('Can flexible schedules reduce pressure on public transport?', 'They can spread demand if enough organisations participate and workers have genuine choice. However, school times and fixed service roles still concentrate some journeys. Flexibility is one useful measure, not a complete substitute for adequate capacity and reliable transport.'),
    q('How can flexibility become unfair within a workplace?', 'It may create unequal access if only some roles qualify or if flexible staff are quietly expected to cover extra work. Transparent reasons and alternative support for other roles are important. Fairness requires examining practical effects, not simply offering the same wording in a policy.'),
    q('Should work be judged mainly by time spent or results produced?', 'Results are important, but they can be difficult to measure and may depend on teamwork or long-term effort. Time also matters where availability is part of the service. A balanced assessment considers the nature of the work rather than treating one measure as suitable for every job.'),
    q('Why is reviewing a new policy better than relying only on initial enthusiasm?', 'Early enthusiasm may reflect novelty rather than lasting improvement, while problems may emerge gradually. A review can compare actual effects with the original purpose. It should include people affected differently, so positive experiences from one group do not hide burdens transferred to another.'),
  ] },
  { topic: 'A repaired toy kept for its meaning', band: 8, part1: [
    q('What makes an old possession worth keeping?', 'Its connection with a person or experience matters more than age alone. I do not keep every old item, but one familiar object can carry a memory more vividly than several photographs.'),
    q('Would you prefer an old object to retain signs of use?', 'Often yes, as long as it remains safe and useful. A worn surface can show its history, whereas replacing every visible part may remove what made the object meaningful.'),
    q('Do you find it easy to explain why an item matters to you?', 'Usually, although the reason can sound ordinary to another person. The meaning often comes from repeated small experiences rather than a single dramatic event.'),
    q('Have you given away something you no longer needed?', 'I gave a set of kitchen bowls to a friend moving into her first flat. Knowing they would be used made it easier to let them go than storing them indefinitely.'),
    q('Would you like to learn how to restore a small object?', 'I would enjoy learning a careful basic method, especially how to avoid causing more damage. I would not experiment freely on something whose personal or historical value I could not replace.'),
  ], cue: 'Describe an object that someone repaired and kept because it had personal meaning.', points: ['what the object was', 'who kept it', 'what repair was needed', 'and explain why keeping it mattered'], answer: 'My father repaired a small wooden toy truck that had belonged to my brother and me. One wheel had broken, and the paint was scratched from years of play. It had remained in a box after we grew older, so I assumed he might eventually throw it away when clearing the cupboard.\n\nInstead, he made a replacement wheel from a piece of spare wood and fitted it carefully. He did not repaint the whole truck because he wanted to keep the marks from the way we had used it. He told me that he remembered helping us build roads across the living-room floor on rainy afternoons. The toy therefore reminded him of time spent together, not only of our childhood as an abstract period.\n\nKeeping it mattered because the repair made the memory tangible without trying to turn the object into something valuable for sale. We placed it on a shelf where visiting children could see it, although we explained that it was not designed for rough play anymore. I appreciated that my father repaired only what was necessary and left the rest recognisable. The experience helped me understand why another person might keep an object I would initially judge as worn out: its practical function and its emotional function are not always the same.', part3: [
    q('Why can objects have different value to different people?', 'Their meaning depends on personal associations as well as usefulness or market price. An ordinary item may represent years of shared activity for one person and seem unremarkable to another. Recognising that difference helps when deciding what to preserve or give away respectfully.'),
    q('Should restoration aim to remove every sign of age?', 'Not necessarily, because signs of use may be part of the object’s significance. The aim should depend on its purpose, condition and value. Restoring safe function can be different from making something appear new, and excessive changes may erase information people wanted to preserve.'),
    q('How can families avoid keeping more objects than they can manage?', 'They can discuss which items carry particular meaning and preserve the stories behind them, rather than assuming everything old must remain. Photographs or written accounts may sometimes help. The decision should still respect attachments instead of treating limited space as a reason to dismiss every memory.'),
    q('Is repairing a sentimental item always worthwhile?', 'It depends on safety, cost and the risk of losing what makes it meaningful. Some repairs are modest and valuable, while others could cause further damage. Seeking informed advice can help; emotional importance does not require attempting a restoration that is impractical or beyond one’s skill.'),
    q('Can possessions communicate family history to younger people?', 'They can provide a concrete starting point for stories, especially when someone explains how the object was used. Without that explanation, the item may become only clutter. Preserving context and inviting questions can make the connection accessible without expecting younger people to feel exactly the same attachment.'),
  ] },
  { topic: 'A neighbourhood mural made with residents', band: 6, part1: [
    q('Do you notice artwork on walls when walking through a town?', 'I notice it if it changes a familiar street or has a clear connection with the area. I sometimes stop to look, but I do not photograph every painted wall.'),
    q('Would you enjoy helping with a public art activity?', 'I would enjoy a manageable task, such as painting a background section. I would want guidance so my contribution fitted the shared design rather than creating extra work for the artist.'),
    q('What kind of image would you choose to represent your area?', 'I might choose the river and the small market because both are part of ordinary local life. A famous building alone would not show how people actually use the place.'),
    q('Do colours change how you feel about an ordinary street?', 'They can make a dull wall more welcoming, but the design needs to fit the setting. Very strong colours everywhere could become tiring rather than cheerful.'),
    q('Have you ever spoken with someone about an artwork in public?', 'A neighbour and I discussed a mural that included old shop signs. She recognised a name I did not know and explained where the shop had once stood.'),
  ], cue: 'Describe a public artwork that involved people from the local community.', points: ['where the artwork was', 'what it showed', 'how local people were involved', 'and explain your opinion of the result'], answer: 'A mural on the side of our community centre involved several groups of local residents. The wall had been plain and often covered with temporary notices. An artist proposed a design showing everyday journeys through the area, including a child going to school, a market seller and someone walking beside the river.\n\nBefore painting began, the artist held two short discussions where residents could suggest details. Not every suggestion was included, but she explained how the final images needed to work together. Volunteers then helped paint broad areas of colour while the artist completed the more detailed figures. I joined one afternoon and painted part of a background, which required more patience than I expected. Older residents also contributed photographs of former shops that influenced small elements of the design.\n\nI liked the result because it reflected ordinary life rather than presenting the neighbourhood as a perfect tourist scene. Some residents disagreed about the colours, and that discussion continued after the work was finished. However, the wall became a reason for people to stop and talk, which seemed valuable in itself. Taking part also made me appreciate the care needed to turn many suggestions into one coherent image. Community involvement meant contributing to a shared process, not having every individual preference reproduced exactly.', part3: [
    q('How might a wall mural change the way residents use a street?', 'It may encourage people to pause, talk or explore a street they previously crossed without attention. However, a mural cannot compensate for unsafe paths or poor lighting. The effect depends on its setting and connection with local experience, rather than colour alone.'),
    q('Should residents have a say in the design of a public artwork?', 'They should have meaningful opportunities to contribute when the work affects a shared space. An artist still needs room to create a coherent piece. Consultation works better when the possible influence is clear, so residents do not expect every suggestion to become part of the final design.'),
    q('How can a project include people who do not see themselves as artistic?', 'It can offer different roles, such as sharing memories, preparing materials or painting simple sections with guidance. Participation should not require pretending everyone has the same skills. Clear options allow people to contribute without feeling exposed or being assigned work they cannot comfortably do.'),
    q('Does disagreement mean a public artwork was a poor choice?', 'Not necessarily, because taste varies and a shared environment cannot satisfy every preference. The process and reasons matter. If concerns about access, maintenance or representation were ignored, criticism may reveal a real problem; disagreement about colour alone is a different kind of issue.'),
    q('Who should be responsible for maintaining community artwork?', 'Responsibility should be agreed before the work is completed, including funding and what happens if the surface deteriorates. Volunteers may help, but long-term maintenance cannot depend only on initial enthusiasm. Without a plan, a project meant to improve a place may eventually appear neglected.'),
  ] },
  { topic: 'A personal letter worth waiting for', band: 6.5, part1: [
    q('Do you send messages mainly to arrange things or to stay in touch?', 'I use messages for both, but practical arrangements take up more space than I would like. I sometimes send a photograph simply to begin a conversation without needing anything.'),
    q('Would you write a letter to a friend who lived far away?', 'I would for a special occasion or a thoughtful update. A letter takes more effort, which can make the recipient feel that I deliberately set time aside for them.'),
    q('Do you enjoy receiving news from someone after a long silence?', 'Usually, yes, as long as the silence has not involved an unresolved difficulty. It is pleasant to learn how their life has changed without expecting constant contact.'),
    q('What do you include when telling a friend about your week?', 'I usually mention one small event rather than list every task. A specific moment, such as meeting an old classmate, gives the friend something natural to respond to.'),
    q('Do you keep copies of important personal messages?', 'I save a few, particularly messages connected with major changes. Keeping everything would make them difficult to find, so I choose those that still have clear meaning.'),
  ], cue: 'Describe a personal letter or message that you were pleased to receive.', points: ['who sent it', 'what it contained', 'when you received it', 'and explain why receiving it pleased you'], answer: 'I was pleased to receive a letter from a friend who had moved to a small island for work. We had exchanged short messages, but her internet connection was unreliable, and our conversations often stopped halfway through. The letter arrived several weeks after she had written it, when I had almost forgotten that she said she would send one.\n\nIt described ordinary details of her new routine: the early ferry, a shop that closed for lunch and the difficulty of learning everyone’s names. She included a small sketch of the view from her room because she did not have a printed photograph. What I liked most was a paragraph about an unexpected kindness from a neighbour who helped her carry groceries in strong wind. The account made the place feel real rather than like a distant holiday destination.\n\nReceiving it pleased me because it gave us a slower, fuller kind of conversation. I could read it again without worrying that a reply was expected immediately. I wrote back with news from home and asked about the neighbour. The delay did not make the letter less valuable; it gave it a different rhythm from our usual messages. I still use quick communication, but the letter reminded me that staying connected does not always require instant exchange.', part3: [
    q('Can slower forms of communication offer advantages?', 'They can encourage more reflection and allow a fuller account without the pressure of immediate response. That suits some personal exchanges, though it is unsuitable for urgent arrangements. The value depends on the purpose, rather than assuming faster communication is always more meaningful or useful.'),
    q('Why do people sometimes feel obliged to answer messages immediately?', 'Visible notifications and expectations within a group can make delay feel like neglect. Some services also show when a message has been read. Agreeing on reasonable response times can reduce pressure, especially when the communication is not urgent or when people have different daily schedules.'),
    q('Does frequent contact necessarily make a friendship stronger?', 'Not necessarily, because the quality of attention matters as well as frequency. Brief contact can maintain closeness, but constant exchange may remain superficial. Some friendships tolerate long pauses because both people understand the relationship and respond thoughtfully when they do communicate.'),
    q('How can people keep in touch across different time zones?', 'They can use messages that do not require an immediate reply and arrange occasional calls at mutually reasonable times. Flexibility should work in both directions. Assuming one person must always stay awake late can make a friendly connection feel like an unequal obligation.'),
    q('Should personal messages be preserved for future readers?', 'That can be meaningful with appropriate permission, but privacy should come before curiosity. Writers may reveal things intended for only one recipient. Preserving a message does not automatically create a right to publish it, even if the account later seems historically interesting.'),
  ] },
  { topic: 'Learning from an unsuccessful prototype', band: 7, part1: [
    q('Do you enjoy testing whether an idea works in practice?', 'I enjoy a small experiment when the result is not too costly. Seeing what actually happens is often more informative than discussing an idea endlessly without trying it.'),
    q('How do you feel when an early attempt fails?', 'I am disappointed at first, but I try to identify one useful detail before starting again. Otherwise I risk repeating the same method with only more effort.'),
    q('Would you rather solve a practical problem alone or with others?', 'For an unfamiliar problem, a small group is helpful because people notice different things. I still like time alone to examine one part without the discussion moving too quickly.'),
    q('Have you used a drawing to explain an idea?', 'I sketched a cupboard arrangement when discussing a room with my partner. The drawing was rough, but it made the narrow passage obvious in a way my description had not.'),
    q('Do you keep records of things you try?', 'I make brief notes if I expect to repeat the task. A photograph and one sentence about the result are often enough to prevent me from forgetting why I changed the method.'),
  ], cue: 'Describe an unsuccessful attempt that led to a better result later.', points: ['what you were trying to make or do', 'why the first attempt failed', 'what you changed', 'and explain what the later result taught you'], answer: 'An unsuccessful attempt helped our study group understand a simple design problem. We were asked to build a bridge from cardboard that could hold a small weight across a fixed gap. Our first version looked neat, but we had concentrated on the surface and given little thought to how the sides supported it.\n\nWhen we placed the weight in the middle, the bridge bent quickly. We were tempted to add several more layers of cardboard, but one member suggested examining where it had folded. We marked the weak points and compared a flat strip with a folded shape using spare pieces. Then we rebuilt the sides with folds and changed the way they joined the top. We kept the span and test weight the same so we could compare the results fairly.\n\nThe later bridge held the weight, although it looked less polished. The result taught us that a useful test is not simply a chance to prove an idea correct. It can show which part of the idea needs attention. We also learned that adding more material is not always the best response to failure. I remember the activity because the first mistake gave us a clearer question, and answering that question was more satisfying than producing something attractive on the first try.', part3: [
    q('Why can unsuccessful experiments be valuable in learning?', 'They reveal the limits of an assumption and give learners a specific problem to investigate. The value depends on examining the result rather than merely trying again. A failed attempt is less informative if nobody records the conditions or considers why the outcome differed from expectations.'),
    q('Should schools reward the process as well as the final product?', 'They should recognise reasoning, testing and improvement, especially when those are part of the learning goal. The final product still matters, but it may hide how much understanding was developed. Assessment needs clear criteria so effort alone does not replace evidence of thoughtful work.'),
    q('How can a team avoid defending its first idea unnecessarily?', 'It can agree that testing the idea is more important than protecting ownership of it. Looking at shared evidence helps shift discussion away from personal pride. A leader should also allow questions early, before so much time is invested that revision feels like an admission of failure.'),
    q('Is trial and error suitable for every problem?', 'No, some situations involve risks that make uncontrolled experimentation unacceptable. Trial and error is useful within safe, limited conditions, especially when mistakes are recoverable. In higher-risk settings, established knowledge, careful modelling and expert supervision are needed before practical testing.'),
    q('What distinguishes useful persistence from repeating a poor method?', 'Useful persistence includes observation and adjustment, not simply continuing for longer. Repetition can improve a skill when the method is sound, but it can also reinforce an error. The key is whether the person learns from feedback and changes the part that is preventing progress.'),
  ] },
  { topic: 'An old cinema given a new purpose', band: 7.5, part1: [
    q('Do you like buildings that have kept parts of their original design?', 'I do when those features remain useful or help explain the building’s history. Keeping an old entrance can be interesting, but I would not want essential access sacrificed only for appearance.'),
    q('What do you notice first when entering an unfamiliar building?', 'I look for where to go and whether the signs are clear. Once I know the route, I notice the light, materials and sounds.'),
    q('Have you attended an event in a converted building?', 'I attended a book fair in a former warehouse. The high ceiling made it feel spacious, though the organisers needed extra signs because the layout was unfamiliar.'),
    q('Would you enjoy learning about a building’s previous use?', 'Yes, a short explanation can make architectural details meaningful. I prefer knowing why a feature exists rather than simply being told that the building is old.'),
    q('What makes a community building welcoming to you?', 'An obvious entrance, clear opening information and staff who acknowledge visitors help. Expensive decoration matters less than not feeling uncertain about whether I am allowed to use the space.'),
  ], cue: 'Describe a building that has been adapted for a new use.', points: ['what the building used to be', 'what it is used for now', 'which changes you noticed', 'and explain your opinion of the adaptation'], answer: 'A former cinema near my hometown has been adapted into a community learning centre. The cinema closed several years ago, and for a while the building looked neglected. I visited after the conversion to attend a short photography talk and was curious about how such a large, specialised room could be used differently.\n\nThe main auditorium had been divided into a hall and smaller teaching spaces. The original entrance canopy remained, and a few photographs in the lobby showed the cinema when it was operating. New ramps and clearer internal signs made the route easier to understand. Some old seats had been kept along one wall, but most had been removed so the hall could accommodate different arrangements. I noticed that the design preserved selected features rather than trying to keep every part unchanged.\n\nI thought the adaptation was successful because the building had become useful again without losing all connection with its past. The new purpose also suited the location, which was accessible by bus and close to residential streets. I would not assume conversion is always cheaper or better than new construction; this building had particular advantages. What pleased me was seeing a familiar place participate in current community life instead of remaining an empty reminder of an activity that had ended.', part3: [
    q('What factors should guide a decision to reuse an old building?', 'Its condition, location and ability to meet current needs should be considered alongside historical significance. Reuse can preserve character and materials, but adaptation may be costly or impractical. A responsible decision compares realistic options rather than assuming age alone makes preservation either necessary or pointless.'),
    q('Should every original feature be retained during a conversion?', 'No, some features may prevent safe or useful access, while others meaningfully explain the building’s history. Selecting what to retain requires judgement and documentation. Preserving everything can produce a space that is difficult to use, but removing everything may erase the reason adaptation was worthwhile.'),
    q('How can a building’s new use support local identity?', 'It can connect familiar features with activities that residents now need, making the past part of ongoing life. Involving local users helps identify suitable functions. Identity is not preserved only by appearance; it also depends on whether people can continue to enter and use the place.'),
    q('Why might residents disagree about a conversion project?', 'Some value memories associated with the original use, while others focus on current services or costs. Both perspectives can reveal important concerns. Transparent information about constraints and alternatives helps discussion move beyond treating supporters as careless or opponents as unwilling to accept any change.'),
    q('Is public access more important than preserving a building unchanged?', 'The two aims should first be explored together, but access often requires sensible adaptation. A perfectly preserved building that nobody can use has limited public value. The appropriate balance depends on its significance and vulnerability, with changes designed to be as careful and informative as possible.'),
  ] },
  { topic: 'Completing a difficult local walk together', band: 8, part1: [
    q('Do you like setting goals for leisure activities?', 'I sometimes set a modest goal, such as completing a longer walking route. I avoid turning every outing into a target because enjoyment and recovery are important too.'),
    q('Would you prefer encouragement during a challenge or afterwards?', 'During the difficult part, calm practical encouragement helps. Afterwards I appreciate someone recognising the effort, but I do not need a large celebration for every small improvement.'),
    q('How do you judge whether a goal is realistic?', 'I compare it with what I can currently do and leave room for unexpected conditions. A goal that requires everything to go perfectly is more fragile than it first appears.'),
    q('Do you enjoy preparing for an activity with a friend?', 'Yes, if we can discuss different expectations honestly. Preparation is less enjoyable when one person assumes the other wants exactly the same pace or level of difficulty.'),
    q('What would make you postpone an outdoor goal?', 'Unsafe conditions or illness would be clear reasons. I would rather attempt the activity when it is sensible than treat a planned date as more important than the purpose of the goal.'),
  ], cue: 'Describe an achievement that you shared with another person.', points: ['what you achieved', 'who did it with you', 'how you prepared or worked together', 'and explain why sharing it mattered'], answer: 'I completed a long local walking route with a friend after several shorter practice walks. Neither of us was especially fit, and the route included a hill that had discouraged us during an earlier visit. We decided to treat completing it comfortably as the goal, rather than trying to finish within an impressive time.\n\nWe prepared by walking regularly and checking the route information, including where we could shorten the journey if necessary. On the day, we carried water and simple food, started early enough to avoid rushing and agreed to stop before either person became exhausted. My friend kept the pace steady on the hill, while I checked the turns because I was more comfortable reading the route description. Near the end, we took a longer break than planned and still finished before evening.\n\nSharing the achievement mattered because each of us contributed something the other found difficult. We also knew how much preparation had gone into an outcome that might look ordinary to an experienced walker. We celebrated with a meal nearby, not because we had done anything remarkable, but because we had followed through sensibly. The experience made me value a goal that strengthened cooperation rather than comparing us with people who had different abilities or much more experience.', part3: [
    q('How can shared goals strengthen a relationship?', 'They give people opportunities to coordinate, encourage and learn about each other’s needs. The benefit depends on expectations being discussed rather than assumed. A shared goal can create tension if one person treats their own preferred pace or ambition as the standard everyone must follow.'),
    q('Should an achievement be judged mainly by how difficult it looks to others?', 'No, visible difficulty may not reflect the person’s starting point or circumstances. A modest result can require substantial learning or persistence. External standards are useful in formal assessment, but personal achievement also involves progress that outsiders may not be able to see.'),
    q('What can make encouragement unhelpful?', 'It can become pressure if it dismisses a real limitation or implies that stopping is always weakness. Useful encouragement listens and supports a sensible next step. Saying someone can do anything may sound positive while leaving them less able to judge the actual situation.'),
    q('Is celebrating progress likely to improve motivation?', 'It can reinforce attention to meaningful improvement and make sustained effort feel worthwhile. However, rewards should not become the only reason to continue. A proportionate celebration that recognises the process may support motivation better than constant comparison or increasingly elaborate prizes.'),
    q('How should people respond when a shared goal becomes unrealistic?', 'They should review the reason for the goal and adjust the plan openly, rather than allowing one person to hide difficulties. Postponing or choosing an alternative may preserve the useful purpose. Completing the original plan is not the only possible evidence of commitment or cooperation.'),
  ] },
  { topic: 'A useful disagreement before buying a camera', band: 7, part1: [
    q('Do you ask someone’s opinion before making a larger purchase?', 'I ask if they know the product or understand how I will use it. Collecting opinions from everyone can become confusing when their priorities differ from mine.'),
    q('Would you buy second-hand electronic equipment?', 'I would consider it if I could check the condition and the seller’s information. A low price alone would not compensate for uncertainty about whether it worked reliably.'),
    q('How do you decide which product features matter?', 'I begin with the tasks I actually expect to do. Advertisements can make every feature sound essential, so writing down my needs helps me avoid paying for unnecessary complexity.'),
    q('Have you delayed a purchase after comparing options?', 'I delayed buying a printer when I realised I only needed one occasionally. Using a nearby printing service was simpler, and the delay prevented me from buying something difficult to justify.'),
    q('Do you enjoy researching products online?', 'Only up to a point. Useful comparisons help, but reading dozens of similar reviews can make a manageable choice feel endless without adding much reliable information.'),
  ], cue: 'Describe a disagreement that helped you make a better choice.', points: ['what choice you were making', 'who disagreed with you', 'what reasons they gave', 'and explain what you decided'], answer: 'A disagreement with my partner helped me choose a camera more sensibly. I wanted one for travel photographs and had become interested in a model with several advanced features. My partner did not think it was a poor camera, but she questioned whether I would use what made it expensive.\n\nAt first I felt she was dismissing my interest. Then she asked me to describe the photographs I actually wanted to take and which problems my phone could not solve. We listed a few practical needs, including comfortable handling and better control in low light. She also pointed out that a heavy camera might remain in the hotel if carrying it became inconvenient. We visited a shop to compare the weight and controls rather than arguing only from online descriptions.\n\nI chose a simpler used model after checking its condition. The decision saved money, but the more important result was that I understood why the camera suited me. The disagreement was useful because it challenged the link I had made between more features and better value. My partner listened when I explained the benefits that genuinely mattered, so the discussion did not become a demand that I abandon the purchase. I now use the camera regularly and feel less tempted by specifications unrelated to my actual photographs.', part3: [
    q('Why can more information make a purchase decision harder?', 'Information may include features that are irrelevant to the buyer or comparisons based on different priorities. More detail is useful only when organised around the intended use. Without that focus, research can create uncertainty and make minor differences seem more important than they are.'),
    q('How can disagreement support better decision-making?', 'It can reveal assumptions and alternatives that one person has overlooked, provided the reasons are explained respectfully. The aim should be examining the choice rather than winning the argument. A discussion becomes less useful when criticism of the idea is treated as criticism of the person.'),
    q('Should manufacturers offer simpler products as well as advanced ones?', 'Yes, because users have different needs and may value reliability or ease of use more than additional functions. Simpler should not mean poorly made. Clear differences between models help customers choose appropriately instead of assuming the most complicated option is always the best.'),
    q('What should buyers know before choosing a used product?', 'They should understand its condition, any known faults and what protection or return arrangement is available. Some products require specialist checks. A used purchase can be sensible, but uncertainty should be reflected in the decision rather than ignored because the initial price is attractive.'),
    q('Can online reviews replace trying a product personally?', 'They can reveal recurring issues and broaden the available evidence, but they cannot fully show how an item feels to a particular user. Reviews may also reflect different expectations. When handling or fit matters, a personal trial provides information that ratings alone cannot supply.'),
  ] },
  { topic: 'A conversation that clarified a decision about moving', band: 8, part1: [
    q('What would matter most if you moved to another area?', 'I would consider daily travel and access to people I rely on. An attractive home could become inconvenient if it separated me from ordinary support or added a tiring journey.'),
    q('Do you like discussing important choices with family?', 'I value their perspective, but I explain whether I need information or advice. Family members may have strong preferences, so clarifying the question helps keep the discussion useful.'),
    q('Have you changed your mind after talking through a plan?', 'Yes, explaining the plan aloud sometimes reveals a problem I had not noticed. The other person does not always need to offer a solution; a careful question can be enough.'),
    q('Would you enjoy living somewhere completely unfamiliar?', 'For a time, I would enjoy the discovery, but I would also want practical ways to meet people. An unfamiliar place can be exciting and lonely at the same time.'),
    q('How do you feel when a decision cannot be made quickly?', 'I can find the uncertainty tiring, but I try to separate missing information from simple hesitation. Gathering one relevant fact is more useful than repeatedly reviewing the same possibilities.'),
  ], cue: 'Describe a conversation that helped you understand your own priorities.', points: ['who you spoke with', 'what decision you were considering', 'what they asked or said', 'and explain what became clearer afterwards'], answer: 'A conversation with an older friend helped me understand my priorities when I was considering moving closer to work. The new area would shorten my commute, but it was farther from relatives and the places I used regularly. I kept comparing rent and travel times without reaching a decision.\n\nMy friend listened and then asked me to describe an ordinary week rather than list the advantages of each flat. As I explained when I visited family, exercised and studied, I realised that the shorter commute would not automatically mean more usable time. Several other journeys would become longer. She also asked which difficulties were temporary and which would continue, so I could distinguish a busy period at work from the everyday routine I hoped to maintain. She did not tell me where to live.\n\nAfterwards, it became clearer that access to familiar support mattered more to me than I had admitted in the comparison. I decided to keep looking within a smaller area rather than accept the first flat near the office. The conversation was helpful because it changed the question from which option looked best on paper to which option fitted the life I actually wanted. I still had practical constraints, but I could evaluate them with a more coherent sense of what I was trying to protect.', part3: [
    q('Why are housing decisions difficult to reduce to price and distance?', 'They affect relationships, routines and access to services as well as finances. Some consequences are hard to measure before moving. Price and distance remain important, but a useful comparison also considers how the location changes ordinary activities and the support available in daily life.'),
    q('What makes someone a good listener during an important decision?', 'They allow the person to explain priorities, ask clarifying questions and avoid imposing an immediate answer. Listening does not require silent agreement with every assumption. A useful question can expose a difficulty while leaving responsibility for the final choice with the person affected.'),
    q('Should people move primarily for career opportunities?', 'Career opportunities can be a strong reason, but they should be considered with family needs, living costs and personal wellbeing. The right balance differs between people and stages of life. Treating career advancement as the only serious priority overlooks other responsibilities and sources of stability.'),
    q('How can cities make it easier for newcomers to build connections?', 'Accessible community spaces, clear local information and affordable activities can provide opportunities to meet others. Newcomers also need stable housing and transport to participate. Social connection cannot simply be ordered, but practical barriers can be reduced so people have a genuine chance to develop it.'),
    q('Is remaining in a familiar place necessarily a sign of avoiding change?', 'No, it may reflect a considered choice about support, responsibilities or the quality of daily life. Familiarity can also become a reason to avoid useful opportunities, so the motives should be examined. The decision is better judged by its reasoning than by whether it involves moving.'),
  ] },
];
